/**
 * Quote-only variant: the feed_facts `quote` field must stay a byte-for-byte
 * substring of the traced chunk text it was copied from (verbatim-quote lint
 * contract, plan section 2.2) — collapsing internal whitespace like
 * `truncateForCompact` does would turn a genuine `\n`/`\t`/double-space span
 * in the source into a string the raw chunk text no longer contains. `trim`
 * (dropping leading/trailing whitespace) and prefix-slicing are both safe:
 * either operation only shortens a substring from one end, so the result
 * stays a contiguous substring of whatever the analyst actually copied.
 */
function truncateQuotePreservingBytes(raw: string, limit: number, ctx: CompactContext, path: string): string {
  const trimmed = raw.trim();
  if (trimmed.length <= limit) return trimmed;
  ctx.diagnostics.truncated_fields.push(path);
  return trimmed.slice(0, Math.max(0, limit - 1)).trimEnd() + '…';
}"
}

